__ht__function(json, dm, view, datas) {// ===== 获取 GraphView 和数据模型 =====
var view = graphView.getView();
var dm = graphView.dm();
//滚动条不可见
graphView.setScrollBarVisible(false);
// 获取实时纵坐标基准点
var rolly1 = dm.getDataByTag('roll-y1');
var rolly2 = dm.getDataByTag('roll-y2');
var rolly3 = dm.getDataByTag('roll-y3');

// ✅ 使用函数动态获取 Y 坐标
function getYTrack(index) {
    switch (index) {
        case 0: return rolly1.getPosition().y;
        case 1: return rolly2.getPosition().y;
        case 2: return rolly3.getPosition().y;
        default: return 0;
    }
}

// 获取热检横坐标基准点
var TRACK_POSITION_MAP = getTrackPositionMap();
// 1. 先获取轨道坐标映射表（名称 → 整数坐标）
function getTrackPositionMap() {
  const map = {};
  dm.each(item => {
    const tag = item.getTag();
    if (tag && tag.startsWith('track-')) {
      const match = tag.match(/track-(\d+)-(.+)/);
      if (!match) return;
      
      const trackNum = parseInt(match[1], 10);
      const name = match[2];
      const baseX = item.getX();
      const offset = (trackNum - 1) * 1800;
      const finalX = baseX + offset;
      
      // 忽略小数点，取整数
      map[name] = Math.floor(finalX);
    }
  });
  return map;
}

console.log(TRACK_POSITION_MAP);

// 轨道配置
var segmentLength = 1800;
var allSteelLines = {};
var lastPositions = {};
var animationFrames = {};
var steelLineShapesCollection = [];

// ===== 工具函数：创建钢条 shape =====
function createSteelLineShapes(steel) {
    const lineShapes = [];

    for (let i = 0; i < 3; i++) {
        let line = new ht.Shape();
        line.setTag(
            `steel-${steel.slabNo}-track-${i}`
        );
        line.setStyle(
            'label',
            steel.label
        );

        line.setStyle(
            'shape.border.color',
            steel.borderColor
        );
        line.setStyle('label.position', "3");
        line.setStyle('label.font', "16px arial, sans-serif");
        line.setStyle('label.color', "rgb(255,255,255)");
        line.setStyle('shape.border.width', 6);
        line.setStyle('shape.type', 'polyline');
        // line.setStyle('shadow2', true);
        // line.setStyle('shadow2.color', "rgb(255,72,0)");
        // line.setStyle('shadow2.blur', 10);
        // line.setStyle('shadow2.offset.x', 0);
        // line.setStyle('shadow2.offset.y', 0);
        line.setStyle('2d.movable', false);
        line.setStyle('shape.repeat.image', 'symbols/青岛特钢/扁钢钢坯.json'); // 设置图像并平铺
        line.setLayer('0');
        line.setPoints([]);
        dm.add(line);
        lineShapes.push(line);
    }

    return lineShapes;
}

// ===== 工具函数：更新轨道显示 =====
function updateSteelLines(rollnum, headX, tailX) {
    const lineShapes = allSteelLines[rollnum];
    if (!lineShapes) return;

    // ===== 统一语义 =====
    // headX = 钢头位置
    // tailX = 钢尾位置
    const leftX = Math.min(headX, tailX);
    const rightX = Math.max(headX, tailX);

    for (let i = 0; i < 3; i++) {
        const trackStart = i * segmentLength;
        const trackEnd = trackStart + segmentLength;
        const y = getYTrack(i);

        const visibleStart = Math.max(leftX, trackStart);
        const visibleEnd = Math.min(rightX, trackEnd);

        if (visibleStart < visibleEnd) {
            const relativeStartX = visibleStart - trackStart;
            const relativeEndX = visibleEnd - trackStart;

            lineShapes[i].setPoints([
                {
                    x: relativeStartX,
                    y: y
                },
                {
                    x: relativeEndX,
                    y: y
                }
            ]);
        } else {
            lineShapes[i].setPoints([]);
        }
    }
}

// ===== 工具函数：绘制位移动画函数 =====
function animateSteelLine(rollnum, fromHeadX, fromTailX, fromLen, toHeadX, toTailX, toLen) {
    const duration = 1000;
    const startTime = performance.now();

    if (animationFrames[rollnum]) {
        cancelAnimationFrame(animationFrames[rollnum]);
    }

    function animateFrame(currentTime) {
        const elapsed = currentTime - startTime;
        const t = Math.min(elapsed / duration, 1);

        const currentHeadX = fromHeadX + (toHeadX - fromHeadX) * t;
        const currentTailX = fromTailX + (toTailX - fromTailX) * t;

        updateSteelLines(rollnum, currentHeadX, currentTailX);

        if (t < 1) {
            animationFrames[rollnum] = requestAnimationFrame(animateFrame);
        } else {
            delete animationFrames[rollnum];
        }
    }

    animationFrames[rollnum] = requestAnimationFrame(animateFrame);
}

// ===== 工具函数：动画函数 =====
function drawSteel(
    steel
) {

    const rollnum =
        steel.slabNo;

    if (
        !allSteelLines[
            rollnum
        ]
    ) {

        allSteelLines[
            rollnum
        ] =
            createSteelLineShapes(
                steel
            );

        updateSteelLines(
            rollnum,
            steel.headX,
            steel.tailX
        );

        lastPositions[
            rollnum
        ] = {

            headX:
                steel.headX,

            tailX:
                steel.tailX,

            len:
                steel.length
        };

        return;
    }

    updateSteelStyle(
        steel
    );

    const last =
        lastPositions[
            rollnum
        ];

    if (
        steel.tailX <
        last.tailX
    ) {

        updateSteelLines(
            rollnum,
            steel.headX,
            steel.tailX
        );

    } else {

        animateSteelLine(
            rollnum,

            last.headX,
            last.tailX,
            last.len,

            steel.headX,
            steel.tailX,
            steel.length
        );
    }

    lastPositions[
        rollnum
    ] = {

        headX:
            steel.headX,

        tailX:
            steel.tailX,

        len:
            steel.length
    };
}

//更新钢坯样式
function updateSteelStyle(
    steel
) {

    const shapes =
        allSteelLines[
            steel.slabNo
        ];

    if (!shapes) {

        return;
    }

    shapes.forEach(
        shape => {

            shape.setStyle(
                'label',
                steel.label
            );

            shape.setStyle(
                'shape.border.color',
                steel.borderColor
            );
        }
    );
}

// ✅ 更新全局 shape 集合
function updateSteelLineShapesCollection() {
    steelLineShapesCollection = [];

    Object.values(allSteelLines).forEach(shapeList => {
        steelLineShapesCollection.push(...shapeList);
    });
}

// ===== 主函数：渲染多个钢条数据 =====
// 【修改】适配新数据格式 [rollnum, cardNo, start, end]
function renderMultipleSteels(
    steelList
) {

    const newRollnums =
        new Set();

    // ===== 渲染当前钢坯 =====
    steelList.forEach(
        steel => {

            newRollnums.add(
                steel.slabNo
            );

            drawSteel(
                steel
            );
        }
    );

    // ===== 清理离线钢坯 =====
    Object.keys(
        allSteelLines
    ).forEach(rollnum => {

        if (
            newRollnums.has(
                rollnum
            )
        ) {
            return;
        }

        // 1. 停止动画
        if (
            animationFrames[
                rollnum
            ]
        ) {

            cancelAnimationFrame(
                animationFrames[
                    rollnum
                ]
            );

            delete animationFrames[
                rollnum
            ];
        }

        // 2. 删除Shape
        allSteelLines[
            rollnum
        ].forEach(
            shape =>
                dm.remove(
                    shape
                )
        );

        // 3. 删除缓存
        delete allSteelLines[
            rollnum
        ];

        delete lastPositions[
            rollnum
        ];
    });

    // ===== 更新Shape集合 =====
    updateSteelLineShapesCollection();
}



// ===== 时间流 =====
// SteelFactStore（事实仓库）
const SteelFactStore = {
    initialized: false,
    data: {},

    load() {
        const cache = localStorage.getItem('SteelFactStore');

        if (!cache) return;

        try {
            const obj = JSON.parse(cache);

            this.initialized = obj.initialized || false;
            this.data = obj.data || {};

            console.log('[SteelFactStore] 恢复成功');
        } catch (err) {
            console.error('[SteelFactStore] 恢复失败', err);
        }
    },

    save() {
        localStorage.setItem(
            'SteelFactStore',
            JSON.stringify({
                initialized: this.initialized,
                data: this.data
            })
        );
    }
};

// SteelStateStore（运动状态仓库）
const SteelStateStore = {
    data: {},

    load() {
        const cache = localStorage.getItem('SteelStateStore');

        if (!cache) return;

        try {
            this.data = JSON.parse(cache);

            console.log('[SteelStateStore] 恢复成功');
        } catch (err) {
            console.error('[SteelStateStore] 恢复失败', err);
        }
    },

    save() {
        localStorage.setItem(
            'SteelStateStore',
            JSON.stringify(this.data)
        );
    }
};

// ===== HmdPassStore（热检历史仓库）=====
// 记录每根钢坯每次头/尾经过热检的完整历史
// 用途：
//   1. 下线判断：尾位置经过 No4WaterTankEntryHmd 后不再渲染和位移计算
//   2. 数据校验：检测钢坯信息是否有错传（位置回退、跳过检查点等）
const HmdPassStore = {
    data: {},  // slabNo → { cardNo, furnaceCode, passes: [{type, position, time, x}] }

    load() {
        const cache = localStorage.getItem('HmdPassStore');
        if (!cache) return;
        try {
            this.data = JSON.parse(cache);
            console.log('[HmdPassStore] 恢复成功, 记录数:', Object.keys(this.data).length);
        } catch (err) {
            console.error('[HmdPassStore] 恢复失败', err);
        }
    },

    save() {
        localStorage.setItem('HmdPassStore', JSON.stringify(this.data));
    },

    /**
     * 记录一次热检经过事件
     * @param {string} slabNo   - 钢坯号
     * @param {string} cardNo   - 卡号
     * @param {string} furnaceCode - 炉号
     * @param {string} type     - 'head' | 'tail'
     * @param {string} position - 热检名称
     * @param {string} time     - 经过时间 "YYYY-MM-DD HH:mm:ss.SSS"
     */
    recordPass(slabNo, cardNo, furnaceCode, type, position, time) {
        if (!position || !time) return;

        if (!this.data[slabNo]) {
            this.data[slabNo] = {
                cardNo: cardNo || '',
                furnaceCode: furnaceCode || '',
                passes: []
            };
        }

        const passes = this.data[slabNo].passes;

        // 去重：同一类型、同一热检已记录过，时间是不可变的历史事实，直接跳过
        const lastPass = passes[passes.length - 1];
        if (lastPass && lastPass.type === type && lastPass.position === position) {
            return;
        }

        passes.push({
            type: type,
            position: position,
            time: time,
            x: TRACK_POSITION_MAP[position] || 0
        });

        // 数据校验：检测位置回退
        if (passes.length >= 2) {
            const prev = passes[passes.length - 2];
            if (prev.type === type && prev.x > passes[passes.length - 1].x) {
                console.warn(
                    '[HmdPassStore 异常] 位置回退!',
                    '钢坯:', slabNo,
                    '类型:', type,
                    '从', prev.position, '(x=' + prev.x + ')',
                    '到', position, '(x=' + passes[passes.length - 1].x + ')'
                );
            }
        }

        this.save();
    },

    /**
     * 判断钢坯尾部是否已经过指定热检
     */
    hasTailPassed(slabNo, hmdName) {
        const record = this.data[slabNo];
        if (!record) return false;
        return record.passes.some(p => p.type === 'tail' && p.position === hmdName);
    }
};

//缓存仓库初始化
SteelFactStore.load();
SteelStateStore.load();
HmdPassStore.load();
startSteelSimulator();

// 钢坯最大长度限制（防止后端未发送尾位置时长度异常放大）
var MAX_STEEL_LENGTH = 1500;

//钢坯长度计算
function getSteelLength(steel) {

    return Math.min(
        MAX_STEEL_LENGTH,
        Math.max(
            0,
            steel.headX - steel.tailX
        )
    );

}

//事件：轧线新增钢坯
function addSteelToState(item) {

    if (SteelStateStore.data[item.slabNo]) {
        return;
    }

    // 从头/尾经过的热检位置+时间，通过分区速度正向推算当前位置
    var calcHeadX = 0;
    var calcTailX = 0;
    var lastHeadHmdTime = '';
    var lastTailHmdTime = '';

    if (item.headPosition && item.headTime) {
        var hmdX = TRACK_POSITION_MAP[item.headPosition];
        if (hmdX !== undefined) {
            calcHeadX = forwardSimulatePosition(hmdX, item.headTime, 'head');
            lastHeadHmdTime = item.headTime;
            // 记录初次热检经过
            HmdPassStore.recordPass(
                item.slabNo, item.cardNo, item.furnaceCode,
                'head', item.headPosition, item.headTime
            );
        }
    }

    if (item.tailPosition && item.tailTime) {
        var hmdX = TRACK_POSITION_MAP[item.tailPosition];
        if (hmdX !== undefined) {
            calcTailX = forwardSimulatePosition(hmdX, item.tailTime, 'tail');
            lastTailHmdTime = item.tailTime;
            // 记录初次热检经过
            HmdPassStore.recordPass(
                item.slabNo, item.cardNo, item.furnaceCode,
                'tail', item.tailPosition, item.tailTime
            );
        }
    }

    SteelStateStore.data[item.slabNo] = {

        slabNo: item.slabNo,

        cardNo: item.cardNo,

        furnaceCode:
            item.furnaceCode || '',

        color:
            item.color || 'red',

        state: 'ENTRY',

        headX: calcHeadX,
        tailX: calcTailX,

        headSpeed: 0,
        tailSpeed: 0,

        createTime: Date.now(),
        updateTime: Date.now(),

        _lastHeadHmdTime: lastHeadHmdTime,
        _lastTailHmdTime: lastTailHmdTime
    };

    console.log(
        '[钢坯进入轧线]',
        item.slabNo,
        '推算位置 headX=' + calcHeadX.toFixed(1),
        'tailX=' + calcTailX.toFixed(1)
    );
}

//事件：轧线下线钢坯
function removeSteelFromState(slabNo) {

    const steel = SteelStateStore.data[slabNo];

    // 空字符串、null、undefined 等无效值，直接清理
    if (!steel || typeof steel !== 'object') {
        delete SteelStateStore.data[slabNo];
        return;
    }

    console.log(
        '[钢坯离开轧线]',
        slabNo
    );

    delete SteelStateStore.data[slabNo];

    SteelStateStore.save();
}

//建立事实基线
function buildFactBaseline(rawData) {

    rawData.forEach(item => {

        SteelFactStore.data[item.slabNo] = {
            ...item,
            updateTime: Date.now()
        };

    });

    SteelFactStore.initialized = true;

    SteelFactStore.save();

    console.log(
        '[FactStore] 基线建立完成'
    );
}

//更新真实数据仓库
function updateFactStore(rawData) {

    const oldFactData =
        SteelFactStore.data;

    const newFactData = {};

    rawData.forEach(item => {

        const slabNo = item.slabNo;

        newFactData[slabNo] = {

            ...item,

            updateTime: Date.now()
        };

        // 新钢坯进入（已下线钢坯跳过，防止僵尸死循环）
        if (!oldFactData[slabNo] && !finishedSlabNos[slabNo]) {

            addSteelToState(item);

        }
    });

    // 离线钢坯（服务端不再推送）
    Object.keys(oldFactData).forEach(
        slabNo => {

            if (!newFactData[slabNo]) {

                removeSteelFromState(
                    slabNo
                );

                // 清理下线标记，下次若重新出现可正常接入
                delete finishedSlabNos[slabNo];

            }

        }
    );

    SteelFactStore.data =
        newFactData;

    SteelFactStore.save();
}

//更新同步两个仓库状态
function syncFactToState() {

    const factMap =
        SteelFactStore.data;

    const stateMap =
        SteelStateStore.data;

    // 清理状态仓库中的无效条目（非钢坯对象）
    Object.keys(stateMap).forEach(function(key) {
        var val = stateMap[key];
        if (!val || typeof val !== 'object' || !val.slabNo) {
            console.warn('[StateStore] 清理无效条目:', key);
            delete stateMap[key];
        }
    });

    // ===== 新钢坯 =====
    Object.values(factMap).forEach(fact => {

        const slabNo =
            fact.slabNo;

        if (!stateMap[slabNo]) {

            // 已下线钢坯不重新加入，防止僵尸钢坯死循环
            if (finishedSlabNos[slabNo]) {
                return;
            }

            addSteelToState(fact);

            console.log(
                '[新增钢坯]',
                slabNo
            );
        }

    });

    // ===== 离线钢坯 =====
    Object.keys(stateMap).forEach(
        slabNo => {

            if (!factMap[slabNo]) {

                removeSteelFromState(
                    slabNo
                );

                console.log(
                    '[离线钢坯]',
                    slabNo
                );
            }

        }
    );

    SteelStateStore.save();
}

//所有分区定义
const MILL_ZONES = [
    { name: 'ROLL1',    start: 0,    end: 320  },
    { name: 'ROUGH',    start: 320,  end: 630  },
    { name: 'ROLL2',    start: 630,  end: 1100 },
    { name: 'MIDDLE',   start: 1100, end: 1500 },
    { name: 'ROLL3',    start: 1500, end: 1600 },
    { name: 'PREFINISH',start: 1600, end: 1800 },
    { name: 'ROLL4',    start: 1800, end: 3380 },
    { name: 'FINISH',   start: 3380, end: 3550 },
    { name: 'ROLL5',    start: 3550, end: 5400 }
];

//分区速度初始化配置
const SPEED_CONFIG = {

    ROLL1: {
        headSpeed: 5,
        tailSpeed: 5
    },

    ROUGH: {
        headSpeed: 5,
        tailSpeed: 5
    },

    ROLL2: {
        headSpeed: 5,
        tailSpeed: 5
    },

    MIDDLE: {
        headSpeed: 5,
        tailSpeed: 5
    },

    ROLL3: {
        headSpeed: 5,
        tailSpeed: 5
    },

    PREFINISH: {
        headSpeed: 5,
        tailSpeed: 5
    },

    ROLL4: {
        headSpeed: 5,
        tailSpeed: 5
    },

    FINISH: {
        headSpeed: 5,
        tailSpeed: 5
    },

    ROLL5: {
        headSpeed: 5,
        tailSpeed: 5
    }
};

//轧制判定补充逻辑
const ROLLING_ZONE_NAMES = [
    'ROUGH',
    'MIDDLE',
    'PREFINISH',
    'FINISH'
];

//轧制判定补充逻辑
function getCurrentRollingZone(steel) {

    return MILL_ZONES.find(zone => {

        if (
            !ROLLING_ZONE_NAMES.includes(
                zone.name
            )
        ) {
            return false;
        }

        return (
            steel.tailX < zone.end &&
            steel.headX > zone.start
        );

    }) || null;
}

//分区判定
function getCurrentZone(position) {

    return MILL_ZONES.find(zone => {

        return (
            position >= zone.start &&
            position < zone.end
        );

    }) || null;

}

//分区判定
function getCurrentZoneName(position) {

    const zone =
        getCurrentZone(position);

    return zone
        ? zone.name
        : 'UNKNOWN';

}

//状态判定
function updateSteelPhase(steel) {

    const length =
        getSteelLength(steel);

    if (length < 150) {

        steel.state = 'ENTRY';

        return;
    }

    const rollingZone =
        getCurrentRollingZone(
            steel
        );

    if (rollingZone) {

        steel.state =
            rollingZone.name;

        return;
    }

    steel.state =
        getCurrentZoneName(
            steel.headX
        );
}

//速度求解
function updateSteelSpeed(steel) {

    // 出钢阶段
    if (steel.state === 'ENTRY') {

        steel.headSpeed = 5;

        steel.tailSpeed = 0;

        return;
    }

    const speedConfig =
        SPEED_CONFIG[
            steel.state
        ];

    if (!speedConfig) {

        steel.headSpeed = 0;

        steel.tailSpeed = 0;

        return;
    }

    steel.headSpeed =
        speedConfig.headSpeed;

    steel.tailSpeed =
        speedConfig.tailSpeed;
}

// ===== 钢坯头位置到达1100时停顿5秒（独立函数） =====
var steelPauseTracker = {};

function applySteelPauseAt1100(steel) {
    const PAUSE_POSITION = 1100;
    const PAUSE_DURATION = 5000; // 5秒

    const key = steel.slabNo;

    if (!steelPauseTracker[key]) {
        steelPauseTracker[key] = {
            paused: false,
            pauseStartTime: 0,
            passed: false,
            prevHeadX: steel.headX
        };
    }

    const tracker = steelPauseTracker[key];

    // 检测跨过1100：上一次低于1100，本次大于等于1100
    const crossed1100 = tracker.prevHeadX < PAUSE_POSITION && steel.headX >= PAUSE_POSITION;

    if (crossed1100 && !tracker.paused && !tracker.passed) {
        // 头位置从小于1100跨到1100，开始停顿
        tracker.paused = true;
        tracker.pauseStartTime = Date.now();
        steel.headSpeed = 0;
        steel.tailSpeed = 0;
        console.log('[停顿]', steel.slabNo, '头跨过1100，停顿5秒');
    } else if (tracker.paused) {
        // 停顿中，检查是否已到5秒
        if (Date.now() - tracker.pauseStartTime >= PAUSE_DURATION) {
            tracker.paused = false;
            tracker.passed = true;
            console.log('[停顿]', steel.slabNo, '停顿结束，恢复运动');
        } else {
            steel.headSpeed = 0;
            steel.tailSpeed = 0;
        }
    }

    // 记录本次headX供下次比较
    tracker.prevHeadX = steel.headX;

    // 清理已下线钢坯的追踪数据
    if (!SteelStateStore.data[key]) {
        delete steelPauseTracker[key];
    }
}

//位置求解函数
function updateSteelPosition(
    steel,
    dt
) {

    steel.headX +=
        steel.headSpeed * dt;

    steel.tailX +=
        steel.tailSpeed * dt;

    if (steel.tailX < 0) {

        steel.tailX = 0;
    }

    // 防止后端未发送尾位置时钢坯长度异常放大，强制尾位置跟随头位置
    if (steel.headX - steel.tailX > MAX_STEEL_LENGTH) {

        steel.tailX = steel.headX - MAX_STEEL_LENGTH;
    }
}

// 正向位置推算：从HMD经过位置+时间，推算当前钢坯位置
// @param {number} startX       - 起始位置（HMD的x坐标）
// @param {string} startTimeStr - 经过时间 "YYYY-MM-DD HH:mm:ss.SSS"
// @param {string} speedType    - 'head' | 'tail'（决定用headSpeed还是tailSpeed）
// @returns {number} 推算后的当前位置
function forwardSimulatePosition(startX, startTimeStr, speedType) {
    if (!startTimeStr) return startX;
    if (startX === undefined || startX === null) return 0;

    var startTime = new Date(startTimeStr.replace(' ', 'T')).getTime();
    if (isNaN(startTime)) return startX;

    var now = Date.now();
    var remainingSec = (now - startTime) / 1000;

    if (remainingSec <= 0) return startX;

    var currentX = startX;
    var speedKey = speedType + 'Speed';  // 'headSpeed' or 'tailSpeed'

    // 按顺序遍历所有分区
    for (var i = 0; i < MILL_ZONES.length; i++) {
        var zone = MILL_ZONES[i];

        if (zone.end <= currentX) continue;  // 已走过此分区

        var zoneStart = Math.max(currentX, zone.start);
        var speed = SPEED_CONFIG[zone.name] ? SPEED_CONFIG[zone.name][speedKey] : 0;

        if (speed <= 0) {
            // 此分区速度为0，钢坯无法穿过（如tail在ENTRY阶段），终止推算
            break;
        }

        var zoneDistance = zone.end - zoneStart;
        var timeInZone = zoneDistance / speed;

        if (remainingSec >= timeInZone) {
            currentX = zone.end;
            remainingSec -= timeInZone;
        } else {
            currentX += remainingSec * speed;
            remainingSec = 0;
            break;
        }
    }

    // 超出所有分区，以最后一个分区的速度继续前进
    if (remainingSec > 0) {
        var lastZone = MILL_ZONES[MILL_ZONES.length - 1];
        var lastSpeed = SPEED_CONFIG[lastZone.name] ? SPEED_CONFIG[lastZone.name][speedKey] : 5;
        currentX += remainingSec * lastSpeed;
    }

    return currentX;
}

//离线判定：头位置超出终点，或尾位置经过任一离线检查点即视为下线
var OFFLINE_HMD_LIST = [
    'No4WaterTankEntryHmd',
    'No4ShearBeforeHmd',
    'No4ShearExitHmd',
    'BslHmd'
];

// 已下线的钢坯（防止僵尸钢坯被 syncFactToState / updateFactStore 重新加入）
var finishedSlabNos = {};

function isSteelFinished(steel) {

    if (steel.headX >= 5400) {
        finishedSlabNos[steel.slabNo] = true;
        return true;
    }

    var fact = SteelFactStore.data[steel.slabNo];
    if (fact && fact.tailPosition && OFFLINE_HMD_LIST.indexOf(fact.tailPosition) !== -1) {
        finishedSlabNos[steel.slabNo] = true;
        return true;
    }

    return false;

}

//完全求解器
function updateSteelStates() {

    const now = Date.now();

    const removeList = [];

    Object.values(
        SteelStateStore.data
    ).forEach(steel => {

        const dt =
            (now - steel.updateTime) / 1000;

        steel.updateTime = now;

        // 1 状态判定
        updateSteelPhase(steel);

        // 2 速度求解
        updateSteelSpeed(steel);

        // 2.5 停顿检查：头位置到达1100时停顿5秒（独立函数，可随时移除）
        applySteelPauseAt1100(steel);

        // 3 位置求解
        updateSteelPosition(
            steel,
            dt
        );

        // 4 离线判断
        if (
            isSteelFinished(
                steel
            )
        ) {

            removeList.push(
                steel.slabNo
            );
        }
    });

    removeList.forEach(
        removeSteelFromState
    );
}

