//头尾位置校正函数
function applyPositionCorrection(
    fact,
    steel
) {

    // 钢头校正：有新HMD数据且与上次不同才触发
    if (fact.headPosition && fact.headTime) {
        const hmdX = TRACK_POSITION_MAP[fact.headPosition];

        if (hmdX !== undefined && fact.headTime !== steel._lastHeadHmdTime) {
            // 记录热检经过历史
            HmdPassStore.recordPass(
                fact.slabNo,
                fact.cardNo,
                fact.furnaceCode,
                'head',
                fact.headPosition,
                fact.headTime
            );

            // 正向推算当前位置
            const newHeadX = forwardSimulatePosition(hmdX, fact.headTime, 'head');

            console.log(
                '[钢头校正]', new Date(),
                steel.slabNo,
                steel.headX.toFixed(1),
                '→',
                newHeadX.toFixed(1),
                '(' + fact.headPosition + ' @ ' + fact.headTime + ')'
            );

            steel.headX = newHeadX;
            steel._lastHeadHmdTime = fact.headTime;
        }
    }

    // 钢尾校正：有新HMD数据且与上次不同才触发
    if (fact.tailPosition && fact.tailTime) {
        const hmdX = TRACK_POSITION_MAP[fact.tailPosition];

        if (hmdX !== undefined && fact.tailTime !== steel._lastTailHmdTime) {
            // 记录热检经过历史
            HmdPassStore.recordPass(
                fact.slabNo,
                fact.cardNo,
                fact.furnaceCode,
                'tail',
                fact.tailPosition,
                fact.tailTime
            );

            // 正向推算当前位置
            const newTailX = forwardSimulatePosition(hmdX, fact.tailTime, 'tail');

            console.log(
                '[钢尾校正]', new Date(),
                steel.slabNo,
                steel.tailX.toFixed(1),
                '→',
                newTailX.toFixed(1),
                '(' + fact.tailPosition + ' @ ' + fact.tailTime + ')'
            );

            steel.tailX = newTailX;
            steel._lastTailHmdTime = fact.tailTime;
        }
    }

    // 兼容旧数据格式（只有position没有time），回退到直接跳位置
    if (fact.headPosition && !fact.headTime) {
        const pos = TRACK_POSITION_MAP[fact.headPosition];
        if (pos !== undefined) {
            console.log('[钢头校正(无time)]', steel.slabNo, pos);
            steel.headX = pos;
        }
    }

    if (fact.tailPosition && !fact.tailTime) {
        const pos = TRACK_POSITION_MAP[fact.tailPosition];
        if (pos !== undefined) {
            console.log('[钢尾校正(无time)]', steel.slabNo, pos);
            steel.tailX = pos;
        }
    }
}

